#!/usr/bin/env node
// Development-only. Embeds the pinned browser libraries and the icon subset
// into index.html so the page needs no CDN for its core features.
//
//   node tools/vendor.cjs          rewrite the vendored block in index.html
//   node tools/vendor.cjs --check  exit 1 if the block is out of date
//
// Run it after changing a library version in package.json or after using a new
// Font Awesome icon class in index.html. Ordinary edits need no build step.
const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');

const root = path.resolve(__dirname, '..');
const indexPath = path.join(root, 'index.html');
const BEGIN = '  <!-- VENDOR:BEGIN generated by tools/vendor.cjs from the versions pinned in package.json. Do not edit by hand. -->';
const END = '  <!-- VENDOR:END -->';
const modulePath = (...parts) => path.join(root, 'node_modules', ...parts);
const version = name => JSON.parse(fs.readFileSync(modulePath(name, 'package.json'), 'utf8')).version;
const sri = data => 'sha384-' + createHash('sha384').update(data).digest('base64');

// Text inside <script> must not contain sequences the HTML parser reacts to.
// \x3C is "<" in string, template and regular-expression literals alike.
function embedScript(source) {
  return source
    .replace(/\/\/# sourceMappingURL=.*$/gm, '')
    .replace(/<!--/g, '\\x3C!--')
    .replace(/<(\/?)script/gi, '\\x3C$1script')
    .trim();
}
function embedStyle(source) {
  if (/<\/style/i.test(source)) throw new Error('Stylesheet contains a closing style tag');
  return source.trim();
}

const libraries = [
  { name: 'jszip', file: ['jszip', 'dist', 'jszip.min.js'], note: 'DOCX and PPTX extraction' },
  { name: 'marked', file: ['marked', 'lib', 'marked.umd.js'], note: 'Markdown rendering' },
  { name: 'dompurify', file: ['dompurify', 'dist', 'purify.min.js'], note: 'HTML sanitising' },
  { name: 'highlight.js', package: '@highlightjs/cdn-assets', file: ['@highlightjs/cdn-assets', 'highlight.min.js'], style: ['@highlightjs/cdn-assets', 'styles', 'github-dark.min.css'], note: 'code highlighting' }
];

// Every "fa-solid fa-name" / "fa-regular fa-name" pair used by the page, plus
// icon names that are only ever assigned from script.
function usedIcons(html) {
  const icons = new Map();
  const add = (style, name) => icons.set(`${style}/${name}`, { style, name });
  for (const match of html.matchAll(/fa-(solid|regular) fa-([a-z0-9-]+)/g)) add(match[1], match[2]);
  // A bare quoted name (a lookup table entry) is combined with "fa-solid" at run time.
  for (const match of html.matchAll(/["'`]fa-([a-z0-9-]+)["'`]/g)) {
    if (!['solid', 'regular'].includes(match[1])) add('solid', match[1]);
  }
  return [...icons.values()].sort((a, b) => (a.style + a.name).localeCompare(b.style + b.name));
}

function iconStyles(html) {
  const packageName = '@fortawesome/fontawesome-free';
  let aliases = null;
  const rules = [
    `/*! Font Awesome Free ${version(packageName)} icon subset. Icons: CC BY 4.0, https://fontawesome.com/license/free. Copyright Fonticons, Inc. */`,
    '.fa-solid,.fa-regular{display:inline-block;width:1em;height:1em;vertical-align:-.125em;flex-shrink:0;background-color:currentColor;-webkit-mask:var(--fa-icon) center/contain no-repeat;mask:var(--fa-icon) center/contain no-repeat}'
  ];
  for (const { style, name } of usedIcons(html)) {
    let file = modulePath(packageName, 'svgs', style, `${name}.svg`);
    if (!fs.existsSync(file)) {
      // Older class names such as "fa-search" are aliases of a renamed icon.
      aliases ||= JSON.parse(fs.readFileSync(modulePath(packageName, 'metadata', 'icon-families.json'), 'utf8'));
      const canonical = Object.keys(aliases).find(key => aliases[key].aliases?.names?.includes(name));
      file = canonical ? modulePath(packageName, 'svgs', style, `${canonical}.svg`) : file;
    }
    if (!fs.existsSync(file)) throw new Error(`Font Awesome has no ${style} icon named "${name}"`);
    const svg = fs.readFileSync(file, 'utf8');
    const viewBox = svg.match(/viewBox="0 0 (\d+) (\d+)"/);
    const paths = [...svg.matchAll(/<path[^>]*\sd="([^"]+)"/g)].map(match => match[1]);
    if (!viewBox || !paths.length) throw new Error(`Unexpected SVG structure in ${file}`);
    const body = paths.map(d => `%3Cpath d='${d}'/%3E`).join('');
    const uri = `data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 ${viewBox[1]} ${viewBox[2]}'%3E${body}%3C/svg%3E`;
    const width = Math.round((Number(viewBox[1]) / Number(viewBox[2])) * 1000) / 1000;
    rules.push(`.fa-${style}.fa-${name}{--fa-icon:url("${uri}");width:${width}em}`);
  }
  return rules.join('\n');
}

function buildBlock(html) {
  const lines = [BEGIN];
  for (const library of libraries) {
    const label = `${library.name}@${version(library.package || library.name)}`;
    if (library.style) lines.push(`  <style data-vendor="${label} theme">\n${embedStyle(fs.readFileSync(modulePath(...library.style), 'utf8'))}\n  </style>`);
    const source = fs.readFileSync(modulePath(...library.file), 'utf8');
    lines.push(`  <!-- ${label}: ${library.note}. Source ${sri(source)} -->`);
    lines.push(`  <script data-vendor="${label}">\n${embedScript(source)}\n  </script>`);
  }
  lines.push(`  <style data-vendor="fontawesome-free@${version('@fortawesome/fontawesome-free')} icons">\n${iconStyles(html)}\n  </style>`);
  lines.push(END);
  return lines.join('\n');
}

function splitIndex(html) {
  const start = html.indexOf(BEGIN);
  const end = html.indexOf(END);
  if (start === -1 || end === -1 || end < start) throw new Error('index.html has no VENDOR:BEGIN / VENDOR:END block');
  return { before: html.slice(0, start), block: html.slice(start, end + END.length), after: html.slice(end + END.length) };
}

// Hashes of the PDF.js files the page fetches from the CDN on first PDF use.
function pdfIntegrity() {
  const files = ['legacy/build/pdf.min.mjs', 'legacy/build/pdf.worker.min.mjs'];
  return Object.fromEntries(files.map(file => [file, sri(fs.readFileSync(modulePath('pdfjs-dist', ...file.split('/'))))]));
}

function render(html) {
  const { before, after } = splitIndex(html);
  let output = before + buildBlock(before + after) + after;
  const integrity = pdfIntegrity();
  const pattern = /const PDFJS_INTEGRITY = \{[^}]*\};/;
  if (!pattern.test(output)) throw new Error('index.html has no PDFJS_INTEGRITY table');
  output = output.replace(pattern, () => `const PDFJS_INTEGRITY = {\n${Object.entries(integrity).map(([file, hash]) => `      "${file}": "${hash}"`).join(',\n')}\n    };`);
  return output;
}

module.exports = { render, usedIcons, pdfIntegrity, embedScript, sri, BEGIN, END };

if (require.main === module) {
  const current = fs.readFileSync(indexPath, 'utf8');
  const next = render(current);
  if (process.argv.includes('--check')) {
    if (next !== current) { console.error('index.html vendored block is out of date. Run: node tools/vendor.cjs'); process.exit(1); }
    console.log('Vendored block is up to date.');
  } else {
    fs.writeFileSync(indexPath, next);
    console.log(`Vendored block written (${(Buffer.byteLength(next) / 1024).toFixed(0)} KB total).`);
  }
}
